        UPDATE /*LGVPAY00029.updateSeveranceAllowance*/
               tb_pay_severance_allowance 
		SET  payroll_calculation_set_id  =  #{calculationSetId, jdbcType=NUMERIC}
		    ,payment_yyyymm  =  #{payMonth}
			,employee_no  =  #{employeeNo}
			,period_1st_from  =  #{period1stFrom}
			,period_1st_to  =  #{period1stTo}
			,period_2nd_from  =  #{period2ndFrom}
			,period_2nd_to  =  #{period2ndTo}
			,period_3rd_from  =  #{period3rdFrom}
			,period_3rd_to  =  #{period3rdTo}
			,period_4th_from  =  #{period4thFrom}
			,period_4th_to  =  #{period4thTo}
			,salary_1st  =  #{salary1st}
			,salary_2nd  =  #{salary2nd}
			,salary_3rd  =  #{salary3rd}
			,salary_4th  =  #{salary4th}
			,salary_5th  =  #{salary5th}
			,salary_6th  =  #{salary6th}
			,leaving_reason  =  #{leavingReason}
			,note  =  #{note}
			,adjust_day  =  #{adjustDay}
             , last_update_user_id             = #{applicationUserId}            							/* 최종수정사용자아이디 */
             , last_update_date                = sysdate                 							/* 최종수정일자 */
        WHERE  severance_allowance_id   = #{severanceAllowanceId}

