SELECT /* LGVPAY00029.createDirectCSVDownloadData */ employee_no ,employee_name_local ,employee_name ,period_1st_from ,period_1st_to ,period_2nd_from ,period_2nd_to ,period_3rd_from ,period_3rd_to ,period_4th_from ,period_4th_to ,salary_1st ,salary_2nd ,salary_3rd ,salary_4th ,salary_5th ,salary_6th ,leaving_reason ,note ,adjust_day FROM ( SELECT '1' gubun , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME_LOCAL , 'Employee Eng Name' AS EMPLOYEE_NAME , 'Period 1St From' AS PERIOD_1ST_FROM , 'Period 1St To' AS PERIOD_1ST_TO , 'Period 2Nd From' AS PERIOD_2ND_FROM , 'Period 2Nd To' AS PERIOD_2ND_TO , 'Period 3Rd From' AS PERIOD_3RD_FROM , 'Period 3Rd To' AS PERIOD_3RD_TO , 'Period 4Th From' AS PERIOD_4TH_FROM , 'Period 4Th To' AS PERIOD_4TH_TO , 'Salary 1St' AS SALARY_1ST , 'Salary 2Nd' AS SALARY_2ND , 'Salary 3Rd' AS SALARY_3RD , 'Salary 4Th' AS SALARY_4TH , 'Salary 5Th' AS SALARY_5TH , 'Salary 6Th' AS SALARY_6TH , 'Leaving Reason' AS LEAVING_REASON , 'Note' AS NOTE , 'Adjust Day' AS ADJUST_DAY FROM DUAL UNION ALL SELECT '2' gubun , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , TO_CHAR(tpe.period_1st_from, 'DD/MM/YYYY') AS PERIOD_1ST_FROM , TO_CHAR(tpe.period_1st_to, 'DD/MM/YYYY') AS PERIOD_1ST_TO , TO_CHAR(tpe.period_2nd_from, 'DD/MM/YYYY') AS PERIOD_2ND_FROM , TO_CHAR(tpe.period_2nd_to, 'DD/MM/YYYY') AS PERIOD_2ND_TO , TO_CHAR(tpe.period_3rd_from, 'DD/MM/YYYY') AS PERIOD_3RD_FROM , TO_CHAR(tpe.period_3rd_to, 'DD/MM/YYYY') AS PERIOD_3RD_TO , TO_CHAR(tpe.period_4th_from, 'DD/MM/YYYY') AS PERIOD_4TH_FROM , TO_CHAR(tpe.period_4th_to, 'DD/MM/YYYY') AS PERIOD_4TH_TO , TO_CHAR(tpe.salary_1st) AS SALARY_1ST , TO_CHAR(tpe.salary_2nd) AS SALARY_2ND , TO_CHAR(tpe.salary_3rd) AS SALARY_3RD , TO_CHAR(tpe.salary_4th) AS SALARY_4TH , TO_CHAR(tpe.salary_5th) AS SALARY_5TH , TO_CHAR(tpe.salary_6th) AS SALARY_6TH , tpe.leaving_reason AS LEAVING_REASON , tpe.note AS NOTE , TO_CHAR(tpe.adjust_day) AS ADJUST_DAY FROM tb_pay_severance_allowance tpe , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE em.employee_number = tpe.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code AND tpe.payroll_calculation_set_id = #{calculationSetId, jdbcType=NUMERIC} -- 급여대상자SetId
AND tpe.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
) ORDER BY employee_no asc

