Day' AS MATERNITY_3_DAY , 'Maternity 4 Day' AS MATERNITY_4_DAY , 'Probation Day' AS PROBATION_DAY , 'Adjust Day' AS ADJUST_DAY , 'Total Day' AS TOTAL_DAY , 'Paid Month' AS PAID_MONTH , 'Note' AS NOTE , 'Confirm Flag' AS CONFIRM_FLAG FROM DUAL UNION ALL SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 2 AS ORDER_BY , 'KO16KSC5601' , EMPLOYEE_NO, EMPLOYEE_NAME, ORGANIZATION_NAME, GRADE_CODE , TO_CHAR(START_DATE, 'DD/MM/YYYY') AS START_DATE , TO_CHAR(PROBATION_START_DATE, 'DD/MM/YYYY') AS PROBATION_START_DATE , TO_CHAR(PROBATION_END_DATE, 'DD/MM/YYYY') AS PROBATION_END_DATE , TO_CHAR(MATERNITY_TIMES) , TO_CHAR(PERIOD_1ST_FROM, 'DD/MM/YYYY') AS PERIOD_1ST_FROM , TO_CHAR(PERIOD_1ST_TO, 'DD/MM/YYYY') AS PERIOD_1ST_TO , TO_CHAR(PERIOD_2ND_FROM, 'DD/MM/YYYY') AS PERIOD_2ND_FROM , TO_CHAR(PERIOD_2ND_TO, 'DD/MM/YYYY') AS PERIOD_2ND_TO , TO_CHAR(PERIOD_3RD_FROM, 'DD/MM/YYYY') AS PERIOD_3RD_FROM , TO_CHAR(PERIOD_3RD_TO, 'DD/MM/YYYY') AS PERIOD_3RD_TO , TO_CHAR(PERIOD_4TH_FROM, 'DD/MM/YYYY') AS PERIOD_4TH_FROM , TO_CHAR(PERIOD_4TH_TO, 'DD/MM/YYYY') AS PERIOD_4TH_TO , TO_CHAR(RESIGNATION_DATE, 'DD/MM/YYYY') AS RESIGNATION_DATE , TO_CHAR(working_years),
CASE WHEN (working_years < 1 OR (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0)) = 0) THEN 'N' ELSE 'Y' END AS flag_yn ,
TO_CHAR(salary_1st), TO_CHAR(salary_2nd), TO_CHAR(salary_3rd), TO_CHAR(salary_4th), TO_CHAR(salary_5th), TO_CHAR(salary_6th), TO_CHAR(average_salary), CASE WHEN flag_yn = 'N' THEN '0' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 42 THEN '4 years' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 36 THEN '3.5 years' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 30 THEN '3 years' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 24 THEN '2.5 years' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 18 THEN '2 years' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 12 THEN '1.5 years' WHEN (NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))/30 > 6 THEN '1 year' ELSE '6 months' END AS period_for_cal , TO_CHAR(ROUND(CASE WHEN flag_yn = 'N' THEN 0 WHEN period_for_cal = '4 years' THEN average_salary * 2 WHEN period_for_cal = '3.5 years' THEN average_salary * 1.75 WHEN period_for_cal = '3 years' THEN average_salary * 1.5 WHEN period_for_cal = '2.5 years' THEN average_salary * 1.25 WHEN period_for_cal = '2 years' THEN average_salary * 1 WHEN period_for_cal = '1.5 years' THEN average_salary * 0.75 WHEN period_for_cal = '1 year' THEN average_salary * 0.5 ELSE average_salary * 0.25 END,0)) AS payment , ACC_ORG_CODE, BANK_ACCOUNT_NUMBER, BANK_NAME, leaving_reason, TO_CHAR(maternity_1_day), TO_CHAR(maternity_2_day), TO_CHAR(maternity_3_day), TO_CHAR(maternity_4_day), TO_CHAR(probation_day), TO_CHAR(adjust_day), TO_CHAR((NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0))) AS total_day, TO_CHAR(ROUND(((NVL(maternity_1_day,0) + NVL(maternity_2_day,0) + NVL(maternity_3_day,0) + NVL(maternity_4_day,0) + NVL(probation_day,0) + NVL(adjust_day,0)))/30,0)) AS paid_month, note, confirm_flag FROM ( SELECT employee_no ,EM.FULL_NAME_ENGLISH AS employee_name ,EM.ASSIGNMENT_CATEGORY AS ,em.org_name_local AS organization_name ,em.grade AS grade_code ,EM.DATE_HIRE_SUBSIDIARY AS start_date ,EM.PROBATION_START_DATE AS probation_start_date ,EM.PROBATION_END_DATE probation_end_date ,period_1st_from ,period_1st_to ,period_2nd_from ,period_2nd_to ,period_3rd_from ,period_3rd_to ,period_4th_from ,period_4th_to ,EM.DATE_RETIRE AS resignation_date ,EM.ACC_ORG_CODE ,em.ACCOUNT_NUMBER AS BANK_ACCOUNT_NUMBER ,EM.BANK_NAME AS BANK_NAME ,flag_yn ,salary_1st ,salary_2nd ,salary_3rd ,salary_4th ,salary_5th ,salary_6th ,period_for_cal ,payment ,leaving_reason ,note ,confirm_flag ,CASE WHEN ((NVL2(period_1st_from,1,0) + NVL2(period_1st_to,1,0) + NVL2(period_2nd_from,1,0) + NVL2(period_2nd_to,1,0) + NVL2(period_3rd_from,1,0) + NVL2(period_3rd_to,1,0) + NVL2(period_4th_from,1,0) + NVL2(period_4th_to,1,0))/2) != 0 THEN ((NVL2(period_1st_from,1,0) + NVL2(period_1st_to,1,0) + NVL2(period_2nd_from,1,0) + NVL2(period_2nd_to,1,0) + NVL2(period_3rd_from,1,0) + NVL2(period_3rd_to,1,0) + NVL2(period_4th_from,1,0) + NVL2(period_4th_to,1,0))/2) ELSE NULL END AS maternity_times ,ROUND((EM.DATE_RETIRE - EM.DATE_HIRE_SUBSIDIARY + 1) / 365, 3) AS working_years ,NVL(ROUND((NVL(salary_1st,0) + NVL(salary_2nd,0) + NVL(salary_3rd,0) + NVL(salary_4th,0) + NVL(salary_5th,0) + NVL(salary_6th,0))/ NULLIF((CASE WHEN salary_1st IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN salary_2nd IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN salary_3rd IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN salary_4th IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN salary_5th IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN salary_6th IS NOT NULL THEN 1 ELSE 0 END) , 0), 0), 0) AS average_salary ,CASE WHEN period_1st_from IS NOT NULL THEN period_1st_to - period_1st_from + 1 ELSE 0 END AS maternity_1_day ,CASE WHEN period_2nd_from IS NOT NULL THEN period_2nd_to - period_2nd_from + 1 ELSE 0 END AS maternity_2_day ,CASE WHEN period_3rd_from IS NOT NULL THEN period_3rd_to - period_3rd_from + 1 ELSE 0 END AS maternity_3_day ,CASE WHEN period_4th_from IS NOT NULL THEN period_4th_to - period_4th_from + 1 ELSE 0 END AS maternity_4_day ,CASE WHEN EM.PROBATION_START_DATE IS NULL THEN 0 ELSE EM.PROBATION_END_DATE - EM.PROBATION_START_DATE + 1 END AS probation_day ,adjust_day FROM TB_PAY_SEVERANCE_ALLOWANCE TS, EMP_MASTER EM WHERE TS.payroll_calculation_set_id = #{calculationSetId, jdbcType=NUMERIC} -- 급여대상자SetId AND TS.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER
AND TS.employee_no = #{employeeNo}
AND UPPER(TS.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
) sub) AA ORDER BY ORDER_BY, AA.EMPLOYEE_NO asc
